const dispatchJobPool = () => {
  return (mappedJobs.length ? mappedJobs : filteredJobs.length ? filteredJobs : jobs) as MappedJob[];
};
const dispatchDueDiff = (job: JobRecord) => {
  const raw = (job as any).WorkCompletionDate || (job as any).workCompletionDate || "";
  const date = parseJobDate(raw);
  if (!date) return null;
  return daysBetween(date, dateOnly(new Date()));
};
const dispatchUrgencyScore = (job: JobRecord) => {
  let score = 0;
  const due = dispatchDueDiff(job);
  const second = workflowSecondAttemptInfo(job);
  const workflow = workflowStatus(job) || legacyWorkflowKind(job);
  if (second?.ready) score += 1000;
  else if (second) score += 350;
  if (due !== null && due > 0) score += 700 + due;
  if (due === 0) score += 600;
  if (due !== null && due < 0 && Math.abs(due) <= 2) score += 250;
  if (workflow.includes("NO_ACCESS")) score += 180;
  if (workflow.includes("REFUSED")) score += 120;
  if (workflow.includes("WORK_COMPLETED") || workflow.includes("COMPLETED_BY_OTHERS")) score -= 500;
  return score;
};
const dispatchJobReason = (job: JobRecord) => {
  const due = dispatchDueDiff(job);
  const second = workflowSecondAttemptInfo(job);
  const workflow = workflowLabel(job) || JobStatus.statusLabel(job);
  if (second?.ready) return "72-hour no-access counter matured — ready for 2nd attempt.";
  if (second) return `${second.label} — waiting on 72-hour no-access counter.`;
  if (due !== null && due > 0) return `Overdue by ${due} day${due === 1 ? "" : "s"}.`;
  if (due === 0) return "Due today.";
  if (due !== null && due < 0 && Math.abs(due) <= 2) return `Due in ${Math.abs(due)} day${Math.abs(due) === 1 ? "" : "s"}.`;
  if (/completed|done/i.test(workflow)) return "Completed/final — review paperwork package.";
  return workflow || "Review job details.";
};
const dayAgentEstimatedStopMinutes = (job: JobRecord) => {
  return estimateDayAgentStopMinutes(displayDescription(job), displayLocation(job), DAY_AGENT_DEFAULT_STOP_MINUTES);
};
const dayAgentSmartReason = (job: JobRecord) => {
  const appointment = appointmentDate(job);
  const appointmentHours = appointment ? Math.round((appointment.getTime() - Date.now()) / 3600000) : null;
  const estimate = dayAgentEstimatedStopMinutes(job);
  if (appointmentHours !== null && appointmentHours >= 0 && appointmentHours <= 24) {
    return `Appointment in ${appointmentHours}h · est. ${estimate} min`;
  }
  return `${dispatchJobReason(job)} · est. ${estimate} min`;
};
const dispatchJobLine = (job: JobRecord, index: number) => {
  const address = displayAddress(job);
  const borough = (job as any).borough || (job as any).Borough || "Unknown";
  const amount = displayAmount(job);
  const reason = dispatchJobReason(job);
  return `${index + 1}. ${jobKey(job)} — ${borough} — ${reason}\n   ${address}${amount ? ` — ${amount}` : ""}`;
};
const openDispatchJob = (jobId: string) => {
  const pool = dispatchJobPool();
  const job = pool.find((row) => String(jobKey(row)).trim() === String(jobId).trim());
  if (!job) {
    setActionNotice(`Could not find ${jobId}.`);
    return;
  }
  focusJob(job);
  setActionNotice(`Opened ${jobId}.`);
};

const readPersistedDayAgentLog = () => {
  try {
    const raw = window.localStorage?.getItem(DAY_AGENT_LOG_STORAGE_KEY);
    const parsed = raw ? JSON.parse(raw) : [];
    return Array.isArray(parsed) ? parsed.slice(0, 40) : [];
  } catch {
    return [];
  }
};

const persistDayAgentLog = (entries: Array<{ at: string; text: string; jobId?: string }>) => {
  try {
    window.localStorage?.setItem(DAY_AGENT_LOG_STORAGE_KEY, JSON.stringify(entries.slice(0, 40)));
  } catch {}
};

const appendDayAgentLog = (text: string, job?: JobRecord | null) => {
  const entry = { at: new Date().toISOString(), text, jobId: job ? jobKey(job) : undefined };
  const persistedFallback = [entry, ...readPersistedDayAgentLog()].slice(0, 40);
  persistDayAgentLog(persistedFallback);
  setDayAgentLog((current) => {
    const next = [entry, ...(current.length ? current : readPersistedDayAgentLog())].slice(0, 40);
    persistDayAgentLog(next);
    return next;
  });
};

const manhattanStreetNumber = (job: JobRecord | null | undefined) => {
  const borough = String((job as any)?.borough || (job as any)?.Borough || "").toLowerCase();
  if (!borough.includes("manhattan")) return null;
  const text = `${displayAddress(job)} ${displayLocation(job)}`.toUpperCase();
  const match = text.match(/\b(?:EAST|WEST|E|W)?\s*(\d{1,3})(?:ST|ND|RD|TH)?\s+(?:ST|STREET)\b/);
  if (!match) return null;
  const street = Number(match[1]);
  return Number.isFinite(street) ? street : null;
};

const manhattanExitGuidance = (job: JobRecord | null | undefined) => {
  const street = manhattanStreetNumber(job);
  if (street === null) return "Use live traffic. If Manhattan is selected, confirm whether the stop is above or below 62 St.";
  if (street > 62) return `Above 62 St (${street} St): route north and plan the Bronx exit after upper Manhattan.`;
  return `Below 62 St (${street} St): any bridge/tunnel exit is acceptable; keep routing by traffic.`;
};

const dayAgentContactPlan = (job: JobRecord | null | undefined) => {
  const contact = tenantContactInfo(job);
  const description = displayDescription(job).replace(/\s+/g, " ").slice(0, 220);
  if (!job) return "No job selected yet.";
  if (!contact.appointmentNeeded) {
    return `Public/common area: no tenant call needed. Go to site, review: ${description || "description not listed"}.`;
  }
  if (contact.phone) {
    return `Apartment/contact job: call or text ${contact.name || "tenant"} at ${contact.phone}. Summarize: ${description || "work order details"}. Ask for an access appointment.`;
  }
  return `Apartment/contact job but no phone is listed. Request contact information from HPD, then set appointment.`;
};

const dayAgentRequestedBorough = (command: string, explicit = dayAgentBoroughStart): MapBoroughFilter => {
  const fromCommand = normalizeBoroughKey(command);
  if (fromCommand && fromCommand !== "all") return fromCommand;
  return explicit || "all";
};

const dayAgentPointLabel = (point: { label: string; address?: string }) => {
  return point.label || point.address || "Stop";
};

const dayAgentRoutePoints = (routeJobs = dayAgentRoute, includeReturnToBase = true, routeOrigin: UserLocationState | null = userLocation) => {
  const origin = routeOrigin
    ? { label: "My location", address: "Current GPS", coords: { lat: routeOrigin.lat, lng: routeOrigin.lng } }
    : { label: "Base", address: DAY_AGENT_BASE_ADDRESS, coords: DAY_AGENT_BASE_COORDS };
  const stops = routeJobs
    .slice(0, DAY_AGENT_ROUTE_MAX_STOPS)
    .map((job) => {
      const coords = jobLatLng(job);
      return coords ? { label: jobKey(job), address: displayAddress(job), coords } : null;
    })
    .filter(Boolean) as Array<{ label: string; address: string; coords: { lat: number; lng: number } }>;
  const points = [origin, ...stops];
  if (includeReturnToBase !== false && stops.length) {
    points.push({ label: "Return base", address: DAY_AGENT_BASE_ADDRESS, coords: DAY_AGENT_BASE_COORDS });
  }
  return points;
};

const dayAgentRouteScore = (job: MappedJob, command: string, requestedBorough = dayAgentRequestedBorough(command), routeOrigin: UserLocationState | null = userLocation) => {
  const q = command.toLowerCase();
  const borough = String((job as any).borough || (job as any).Borough || "").toLowerCase();
  const boroughKey = jobBoroughKey(job);
  const street = manhattanStreetNumber(job);
  const coords = jobLatLng(job);
  const origin = routeOrigin || DAY_AGENT_BASE_COORDS;
  const secondAttempt = workflowSecondAttemptInfo(job);
  const appointment = appointmentDate(job);
  const appointmentHours = appointment ? (appointment.getTime() - Date.now()) / 3600000 : null;
  const age = mapDateAgeDays(job);
  const estimatedMinutes = dayAgentEstimatedStopMinutes(job);
  let score = dispatchUrgencyScore(job);
  if (secondAttempt?.ready) score += 6000;
  else if (secondAttempt?.within24) score += 2800;
  if (appointmentHours !== null && appointmentHours >= 0 && appointmentHours <= 12) score += 5200;
  else if (appointmentHours !== null && appointmentHours > 12 && appointmentHours <= 24) score += 3200;
  if (q.includes("appointment") && appointmentHours !== null && appointmentHours >= 0) score += 2600;
  if (typeof age === "number" && age >= 60) score += Math.min(1800, (age - 59) * 24);
  score -= Math.max(0, estimatedMinutes - DAY_AGENT_DEFAULT_STOP_MINUTES) * 6;
  if (requestedBorough !== "all" && requestedBorough !== "unknown") {
    if (boroughKey === requestedBorough) score += 5200;
    else score += 500;
  } else if (q.includes("start") || q.includes("route")) {
    score += 750;
  }
  if (requestedBorough === "manhattan" || q.includes("manhattan")) {
    if (street !== null && street <= 62) score += 450 - street;
    if (street !== null && street > 62) score += 250 - Math.min(street, 130);
  }
  if (q.includes("bronx") && borough.includes("bronx")) score += 3200;
  if (coords) score -= distanceMiles(origin, coords) * (q.includes("near") || requestedBorough === "all" ? 115 : 28);
  if (workflowViewBucket(job) === "archived" || workflowViewBucket(job) === "final") score -= 8000;
  if (!coords) score -= 800;
  return score;
};

const buildDayAgentRoute = (commandText = dayAgentCommand, requestedBoroughOverride?: MapBoroughFilter, routeOrigin: UserLocationState | null = userLocation) => {
  const command = String(commandText || "start").trim();
  const requestedCountMatch = command.match(/\b(\d{1,2})\s+(?:jobs?|stops?)\b/i);
  const requestedStopCount = Math.min(
    DAY_AGENT_ROUTE_MAX_STOPS,
    Math.max(1, Number(requestedCountMatch?.[1] || DAY_AGENT_ROUTE_MAX_STOPS))
  );
  const requestedBorough = requestedBoroughOverride || dayAgentRequestedBorough(command);
  const visibleRouteSource =
    requestedBorough === "nearby"
      ? filteredJobs
      : dispatchJobPool();
  const sourcePool = visibleRouteSource.length ? visibleRouteSource : dispatchJobPool();
  const boroughPool = sourcePool
    .filter((job) => workflowViewBucket(job) !== "archived" && workflowViewBucket(job) !== "final")
    .filter((job) => cleanAddress(job))
    .filter((job) => jobLatLng(job))
    .filter((job) => requestedBorough === "all" || requestedBorough === "unknown" || matchesMapBorough(job, requestedBorough));
  const recentPool = boroughPool.filter((job) => {
      const age = mapDateAgeDays(job);
      return (age !== null && age >= 0 && age <= 90) || hasUpcomingAppointment(job);
    });
  const pool = recentPool.length ? recentPool : boroughPool;
  const sorted = [...pool].sort((a, b) => {
    const aRequested = command.toLowerCase().includes(jobKey(a).toLowerCase()) ? 10000 : 0;
    const bRequested = command.toLowerCase().includes(jobKey(b).toLowerCase()) ? 10000 : 0;
    const score =
      dayAgentRouteScore(b, command, requestedBorough, routeOrigin) + bRequested -
      (dayAgentRouteScore(a, command, requestedBorough, routeOrigin) + aRequested);
    if (score !== 0) return score;
    const aStreet = manhattanStreetNumber(a) || 999;
    const bStreet = manhattanStreetNumber(b) || 999;
    if (aStreet !== bStreet) return aStreet - bStreet;
    return String(jobKey(a)).localeCompare(String(jobKey(b)));
  });
  const route: MappedJob[] = [];
  let cursor = routeOrigin || DAY_AGENT_BASE_COORDS;
  let fieldMinutesUsed = 0;
  const fieldMinutesLimit = (DAY_AGENT_FIELD_END_HOUR - DAY_AGENT_WORK_START_HOUR) * 60;
  const returnMinutesLimit = (DAY_AGENT_BASE_RETURN_HOUR - DAY_AGENT_WORK_START_HOUR) * 60;
  sorted.forEach((job) => {
    if (route.length >= requestedStopCount) return;
    const coords = jobLatLng(job);
    if (!coords) return;
    const travelToJobMinutes = Math.max(4, Math.round((distanceMiles(cursor, coords) / DAY_AGENT_DAY_DRIVE_MPH) * 60));
    const returnToBaseMinutes = Math.max(4, Math.round((distanceMiles(coords, DAY_AGENT_BASE_COORDS) / DAY_AGENT_DAY_DRIVE_MPH) * 60));
    const projectedFieldMinutes = fieldMinutesUsed + travelToJobMinutes + dayAgentEstimatedStopMinutes(job);
    const projectedReturnMinutes = projectedFieldMinutes + returnToBaseMinutes;
    if (projectedFieldMinutes <= fieldMinutesLimit && projectedReturnMinutes <= returnMinutesLimit) {
      route.push(job);
      fieldMinutesUsed = projectedFieldMinutes;
      cursor = coords;
    }
  });
  return route.length ? route : sorted.slice(0, Math.min(requestedStopCount, sorted.length));
};

const dayAgentGoogleRouteUrl = (routeJobs = dayAgentRoute) => {
  const stops = routeJobs.map((job) => displayAddress(job).trim()).filter(Boolean).slice(0, DAY_AGENT_ROUTE_MAX_STOPS);
  if (!stops.length) return "https://www.google.com/maps";
  const origin = userLocation ? `${userLocation.lat},${userLocation.lng}` : DAY_AGENT_BASE_ADDRESS;
  const destination = DAY_AGENT_BASE_ADDRESS;
  const waypoints = stops;
  const params = new URLSearchParams({
    api: "1",
    travelmode: "driving",
    origin,
    destination,
  });
  if (waypoints.length) params.set("waypoints", waypoints.join("|"));
  return `https://www.google.com/maps/dir/?${params.toString()}`;
};

const buildFallbackDayAgentSummary = (points: ReturnType<typeof dayAgentRoutePoints>, routeLatLngs: Array<[number, number]>) => {
  const legs = points.slice(1).map((point, index) => {
    const from = points[index];
    const miles = distanceMiles(from.coords, point.coords);
    const distanceMeters = miles * 1609.344;
    const durationSeconds = Math.max(120, Math.round((miles / 14) * 3600));
    return {
      from: dayAgentPointLabel(from),
      to: dayAgentPointLabel(point),
      durationSeconds,
      distanceMeters,
      label: formatDayAgentLegLabel(durationSeconds, distanceMeters),
      midpoint: {
        lat: (from.coords.lat + point.coords.lat) / 2,
        lng: (from.coords.lng + point.coords.lng) / 2,
      },
    };
  });
  const totalDurationSeconds = legs.reduce((sum, leg) => sum + leg.durationSeconds, 0);
  const totalDistanceMeters = legs.reduce((sum, leg) => sum + leg.distanceMeters, 0);
  return {
    summary: {
      mode: "fallback" as const,
      message: "Estimated connector route. Open Google Route for live turn-by-turn traffic.",
      startedFrom: points[0]?.address || points[0]?.label || "Start",
      returnedToBase: Boolean(points.length > 2 && points[points.length - 1]?.label === "Return base"),
      totalDurationSeconds,
      totalDistanceMeters,
      legs,
    },
    routeLatLngs,
  };
};

async function fetchDayAgentRoadRoute(points: ReturnType<typeof dayAgentRoutePoints>) {
  const coordPath = points
    .map((point) => `${point.coords.lng.toFixed(6)},${point.coords.lat.toFixed(6)}`)
    .join(";");
  const controller = new AbortController();
  const timeoutId = window.setTimeout(() => controller.abort(), DAY_AGENT_ROUTE_FETCH_TIMEOUT_MS);
  const response = await fetch(`https://router.project-osrm.org/route/v1/driving/${coordPath}?overview=full&geometries=geojson&steps=false`, {
    cache: "no-store",
    signal: controller.signal,
  }).finally(() => window.clearTimeout(timeoutId));
  if (!response.ok) throw new Error(`Route service returned ${response.status}`);
  const body = await response.json();
  const route = body?.routes?.[0];
  const geometry = route?.geometry?.coordinates;
  if (!Array.isArray(geometry) || geometry.length < 2) throw new Error("Route service did not return a road geometry.");
  const legs = points.slice(1).map((point, index) => {
    const from = points[index];
    const rawLeg = route?.legs?.[index] || {};
    const distanceMeters = Number(rawLeg.distance || 0);
    const durationSeconds = Number(rawLeg.duration || 0);
    return {
      from: dayAgentPointLabel(from),
      to: dayAgentPointLabel(point),
      durationSeconds,
      distanceMeters,
      label: formatDayAgentLegLabel(durationSeconds, distanceMeters),
      midpoint: {
        lat: (from.coords.lat + point.coords.lat) / 2,
        lng: (from.coords.lng + point.coords.lng) / 2,
      },
    };
  });
  const routeLatLngs = geometry.map(([lng, lat]: [number, number]) => [lat, lng] as [number, number]);
  return {
    summary: {
      mode: "road" as const,
      message: "Road route ready. Use Google Route for live traffic and turn-by-turn navigation.",
      startedFrom: points[0]?.address || points[0]?.label || "Start",
      returnedToBase: Boolean(points.length > 2 && points[points.length - 1]?.label === "Return base"),
      totalDurationSeconds: Number(route.duration || 0),
      totalDistanceMeters: Number(route.distance || 0),
      legs,
    },
    routeLatLngs,
  };
}

async function drawDayAgentRouteLine(routeJobs = dayAgentRoute, routeOrigin: UserLocationState | null = userLocation) {
  if (!mapRef.current) return;
  const points = dayAgentRoutePoints(routeJobs, true, routeOrigin);
  const fallbackLatLngs = points.map((point) => [point.coords.lat, point.coords.lng] as [number, number]);
  if (points.length < 2 || fallbackLatLngs.length < 2) {
    setActionNotice("Choose mapped jobs before drawing the agent route.");
    return;
  }
  const leafletModule = await import("leaflet");
  const L = (leafletModule as any).default || leafletModule;
  if (dayAgentRouteLayerRef.current) {
    mapRef.current.removeLayer(dayAgentRouteLayerRef.current);
    dayAgentRouteLayerRef.current = null;
    dayAgentRouteLineRef.current = null;
  }

  let routeResult: { summary: DayAgentRouteSummary; routeLatLngs: Array<[number, number]> };
  try {
    routeResult = await fetchDayAgentRoadRoute(points);
  } catch {
    routeResult = buildFallbackDayAgentSummary(points, fallbackLatLngs);
    setDayAgentRouteSummary({
      ...routeResult.summary,
      message: "Road route service is unavailable. Use Google or Waze for live navigation; straight connector lines are hidden.",
    });
    setActionNotice("Road route unavailable. I hid the straight green connector lines; use Google/Waze navigation for this route.");
    return;
  }

  const layer = L.layerGroup().addTo(mapRef.current);
  L.polyline(routeResult.routeLatLngs, {
    color: "#e0f2fe",
    weight: 12,
    opacity: 0.78,
    lineCap: "round",
    lineJoin: "round",
  }).addTo(layer);
  dayAgentRouteLineRef.current = L.polyline(routeResult.routeLatLngs, {
    color: DAY_AGENT_ROUTE_DARK,
    weight: 7,
    opacity: 0.96,
    lineCap: "round",
    lineJoin: "round",
  }).addTo(layer);
  L.polyline(routeResult.routeLatLngs, {
    color: DAY_AGENT_ROUTE_ACCENT,
    weight: 2,
    opacity: 0.82,
    lineCap: "round",
    lineJoin: "round",
  }).addTo(layer);
  dayAgentRouteLayerRef.current = layer;
  setDayAgentRouteSummary(routeResult.summary);
  markProgrammaticMapMove();
  const firstLegBounds = L.latLngBounds(
    points.slice(0, Math.min(points.length, 2)).map((point) => [point.coords.lat, point.coords.lng] as [number, number])
  );
  mapRef.current.fitBounds(firstLegBounds.isValid() ? firstLegBounds : dayAgentRouteLineRef.current.getBounds(), {
    animate: true,
    duration: 0.7,
    paddingTopLeft: [58, 120],
    paddingBottomRight: [58, 140],
    maxZoom: 14,
  });
  const addReadableLegLabels = () => {
    if (!mapRef.current || dayAgentRouteLayerRef.current !== layer) return;
    const placed: Array<{ left: number; top: number; right: number; bottom: number }> = [];
    let visibleLabels = 0;
    const routeLabelLimit = typeof window !== "undefined" && window.innerWidth <= 720 ? 0 : Math.min(2, DAY_AGENT_ROUTE_LABEL_LIMIT);
    routeResult.summary.legs.forEach((leg, index) => {
      if (visibleLabels >= routeLabelLimit) return;
      const point = mapRef.current.latLngToContainerPoint([leg.midpoint.lat, leg.midpoint.lng]);
      const box = {
        left: point.x - DAY_AGENT_ROUTE_LABEL_WIDTH / 2,
        top: point.y - DAY_AGENT_ROUTE_LABEL_HEIGHT / 2,
        right: point.x + DAY_AGENT_ROUTE_LABEL_WIDTH / 2,
        bottom: point.y + DAY_AGENT_ROUTE_LABEL_HEIGHT / 2,
      };
      const collides = placed.some((seen) => box.left < seen.right + 8 && box.right + 8 > seen.left && box.top < seen.bottom + 8 && box.bottom + 8 > seen.top);
      if (collides) return;
      placed.push(box);
      visibleLabels += 1;
      L.marker([leg.midpoint.lat, leg.midpoint.lng], {
        interactive: false,
        icon: L.divIcon({
          className: "day-agent-route-leg-label",
          html: `<span>${index + 1}</span><b>${leg.label}</b>`,
          iconSize: [DAY_AGENT_ROUTE_LABEL_WIDTH, DAY_AGENT_ROUTE_LABEL_HEIGHT],
          iconAnchor: [DAY_AGENT_ROUTE_LABEL_WIDTH / 2, DAY_AGENT_ROUTE_LABEL_HEIGHT / 2],
        }),
      }).addTo(layer);
    });
  };
  window.setTimeout(addReadableLegLabels, 760);
  appendDayAgentLog(
    `${routeResult.summary.mode === "road" ? "Road route" : "Estimated route"} ready: ${formatDayAgentDuration(routeResult.summary.totalDurationSeconds)} / ${formatDayAgentDistance(routeResult.summary.totalDistanceMeters)}.`,
    routeJobs[0]
  );
}

const requestFreshDayAgentLocation = () => {
  if (typeof navigator === "undefined" || !navigator.geolocation) {
    setLocationStatus("Location unavailable");
    return Promise.resolve(userLocation);
  }

  return new Promise<UserLocationState | null>((resolve) => {
    const options: PositionOptions = {
      enableHighAccuracy: true,
      maximumAge: 0,
      timeout: 12000,
    };

    setLocationHelpOpen(false);
    setFollowMyLocation(true);
    setLocationStatus("Getting live GPS for route...");
    setActionNotice("Getting your live GPS before building the route.");

    navigator.geolocation.getCurrentPosition(
      (position) => {
        const nextLocation = {
          lat: position.coords.latitude,
          lng: position.coords.longitude,
          accuracy: position.coords.accuracy,
          updatedAt: new Date().toISOString(),
        };
        setUserLocation(nextLocation);
        try {
          window.localStorage.setItem(LOCATION_LAST_STORAGE_KEY, JSON.stringify(nextLocation));
        } catch {}
        setLocationStatus(`Live guide · ±${Math.round((position.coords.accuracy || 0) * 3.28084)} ft`);
        if (geolocationWatchRef.current === null) {
          startLocationTracking({ followMap: true });
        }
        resolve(nextLocation);
      },
      (error) => {
        if (error.code === error.PERMISSION_DENIED) {
          showLocationBlockedHelp();
        } else {
          setLocationStatus(error.code === error.TIMEOUT ? "Location searching..." : "Location unavailable");
          setLocationHelpOpen(true);
          showActionNotice("Could not get fresh GPS yet. Route will use the saved location or base until location is allowed.");
        }
        resolve(userLocation);
      },
      options
    );
  });
};

const startDayAgent = async (commandText = dayAgentCommand, requestedBoroughOverride?: MapBoroughFilter) => {
  const command = String(commandText || "start").trim();
  const requestedBorough = requestedBoroughOverride || dayAgentRequestedBorough(command);
  if (typeof document !== "undefined") {
    (document.activeElement as HTMLElement | null)?.blur?.();
  }
  // Plan immediately from the last saved GPS fix. A route should not pause for a
  // fresh permission request every time the agent starts.
  const routeOrigin: UserLocationState = userLocation || {
    ...DAY_AGENT_BASE_COORDS,
    accuracy: 0,
    updatedAt: new Date().toISOString(),
  };
  if (!userLocation || !isFreshRouteLocation(userLocation)) {
    startLocationTracking({ followMap: false });
  }
  const route = buildDayAgentRoute(command, requestedBorough, routeOrigin);
  setDayAgentStarted(true);
  setDayAgentRoute(route);
  setDayAgentCommand(command);
  setDayAgentBoroughStart(requestedBorough);
  setDayAgentReturnToBase(true);
  setDayAgentRouteHidden(true);
  setDayAgentSelectedStopIndex(0);
  setDayAgentRouteSummary(null);
  if (route[0]) {
    setWorkflowViewFilter("all");
    setMapBoroughFilter(requestedBorough === "unknown" ? "all" : requestedBorough);
    setMapBoardOpen(false);
    setMapMenuOpen(false);
    setDayAgentPanelOpen(false);
    setSelectedOnly(false);
    setFullMap(true);
    appendDayAgentLog(`Started day agent. First stop: ${jobKey(route[0])}. ${manhattanExitGuidance(route[0])}`, route[0]);
    setSelected(null);
    setSelectedOnly(false);
    setDrawerOpen(false);
    void drawDayAgentRouteLine(route, routeOrigin);
    const originLabel = userLocation ? "from your saved location" : "from base while GPS updates";
    setActionNotice(`Workday route ready ${originLabel}: ${route.length} stop${route.length === 1 ? "" : "s"} chosen for 8 AM start, field work to 5 PM, and base return by 6 PM. ${jobKey(route[0])} is first.`);
    speakText(
      `Route ready. ${route.length} stops. First stop ${jobKey(route[0])}, ${displayAddress(route[0])}.`,
      "summary"
    );
  } else {
    appendDayAgentLog("Started day agent, but no active mapped jobs matched.");
    setActionNotice("Day Agent did not find active mapped jobs for this command.");
  }
};

const runDayAgentCommand = () => {
  startDayAgent(dayAgentCommand);
};
const runDispatchChat = (text?: string) => {
  const question = String(text || dispatchQuestion || "").trim();
  if (!question) return;
  const q = question.toLowerCase();
  let rows = [...dispatchJobPool()];
  let title = "Dispatch Answer";
  let recommendation = "Review the top jobs and open the first priority job.";
  const wantsToday = q.includes("today") || q.includes("now") || q.includes("should i") || q.includes("priority") || q.includes("urgent");
  const wantsOverdue = q.includes("overdue") || q.includes("late") || q.includes("od");
  const wantsReadySecond = q.includes("ready") || q.includes("2nd") || q.includes("second attempt") || q.includes("revisit");
  const wantsNoAccess = q.includes("no access") || q.includes("72");
  const wantsCompleted = q.includes("completed") || q.includes("done") || q.includes("paperwork") || q.includes("invoice") || q.includes("affidavit");
  const wantsDueToday = q.includes("due today");
  const wantsDueSoon = q.includes("due soon") || q.includes("next") || q.includes("this week");
  if (q.includes("bronx")) rows = rows.filter((job) => String((job as any).borough || "").toLowerCase().includes("bronx"));
  if (q.includes("brooklyn")) rows = rows.filter((job) => String((job as any).borough || "").toLowerCase().includes("brooklyn"));
  if (q.includes("queens")) rows = rows.filter((job) => String((job as any).borough || "").toLowerCase().includes("queens"));
  if (q.includes("manhattan")) rows = rows.filter((job) => String((job as any).borough || "").toLowerCase().includes("manhattan"));
  if (q.includes("staten")) rows = rows.filter((job) => String((job as any).borough || "").toLowerCase().includes("staten"));
  const wantsRouteMe = q.includes("route me") || q.includes("best route") || q.includes("where should i go") || q.includes("go first") || q.includes("what should i do first") || q.includes("take me");
  if (wantsRouteMe) {
    title = "Route Me Today";
    rows = rows.filter((job) => {
      const due = dispatchDueDiff(job);
      const second = workflowSecondAttemptInfo(job);
      return second?.ready || due === 0 || (due !== null && due > 0) || (due !== null && due < 0 && Math.abs(due) <= 3);
    });
    recommendation = "Open the first job below and tap Waze. Waze will handle live traffic for free. After that, continue down the ranked list.";
  } else if (wantsReadySecond) {
    title = "Ready for 2nd Attempt";
    rows = rows.filter((job) => workflowSecondAttemptInfo(job)?.ready);
    recommendation = "These are the highest no-access priority because the 72-hour counter matured.";
  } else if (wantsNoAccess) {
    title = "No Access / 72-Hour Watchlist";
    rows = rows.filter((job) => {
      const status = workflowStatus(job) || legacyWorkflowKind(job);
      return status.includes("NO_ACCESS") || Boolean(workflowSecondAttemptInfo(job));
    });
    recommendation = "Watch waiting counters and prioritize anything marked ready for 2nd attempt.";
  } else if (wantsCompleted) {
    title = "Completed / Paperwork Review";
    rows = rows.filter((job) => /completed|done/i.test(workflowLabel(job) || JobStatus.statusLabel(job)));
    recommendation = "Review photos, affidavit, invoice package, and documentation before sending.";
  } else if (wantsOverdue) {
    title = "Overdue Jobs";
    rows = rows.filter((job) => {
      const due = dispatchDueDiff(job);
      return due !== null && due > 0;
    });
    recommendation = "Handle the oldest overdue jobs first, unless a 72-hour revisit is ready.";
  } else if (wantsDueToday) {
    title = "Due Today";
    rows = rows.filter((job) => dispatchDueDiff(job) === 0);
    recommendation = "These should be completed or documented today.";
  } else if (wantsDueSoon) {
    title = "Due Soon";
    rows = rows.filter((job) => {
      const due = dispatchDueDiff(job);
      return due !== null && due <= 7 && due >= -2;
    });
    recommendation = "Plan these into the route before they become overdue.";
  } else if (wantsToday) {
    title = "Today’s Dispatch Priority";
    rows = rows.filter((job) => {
      const due = dispatchDueDiff(job);
      const second = workflowSecondAttemptInfo(job);
      return second?.ready || due === 0 || (due !== null && due > 0);
    });
    recommendation = "Start with ready 2nd attempts, then oldest overdue jobs, then due-today jobs.";
  } else {
    title = `Search: ${question}`;
    rows = rows.filter((job) =>
      [
        jobKey(job),
        displayAddress(job),
        (job as any).borough,
        displayDescription(job),
        workflowLabel(job),
        JobStatus.statusLabel(job),
        displayAmount(job),
      ].join(" ").toLowerCase().includes(q)
    );
    recommendation = "I matched jobs based on your question. Ask about urgent, overdue, no access, or due today for better dispatch ranking.";
  }
  rows.sort((a, b) => dispatchUrgencyScore(b) - dispatchUrgencyScore(a));
  const top = rows.slice(0, 8);
  const jobIds = top.map((job) => jobKey(job));
  const answer =
    `${title}\n\n` +
    `${top.length} job(s) found.\n\n` +
    (top.length ? top.map(dispatchJobLine).join("\n\n") : "No matching jobs found.") +
    `\n\nRecommendation:\n${recommendation}`;
  setDispatchMessages((messages) => [
    ...messages,
    { role: "user", text: question },
    { role: "assistant", text: answer, jobs: jobIds },
  ]);
  setDispatchQuestion("");
  setActionNotice("AI Dispatch Chat answered.");
};
