function stickyHeaderClearance(container: HTMLElement | null, stickyHead: HTMLElement | null, gap = 12) {
  if (!container || !stickyHead) return gap;

  const containerRect = container.getBoundingClientRect();
  const headRect = stickyHead.getBoundingClientRect();
  const headOffset = Math.max(0, headRect.top - containerRect.top);

  return headOffset + stickyHead.offsetHeight + gap;
}

function positionSelectedCardInDrawer() {
  const drawer = jobDrawerRef.current;
  if (drawer) {
    const fieldDataTarget =
      drawer.querySelector<HTMLElement>("[data-job-card-description-focus='true']") ||
      drawer.querySelector<HTMLElement>(".job-card-data-strip");
    if (fieldDataTarget) {
      const drawerRect = drawer.getBoundingClientRect();
      const targetRect = fieldDataTarget.getBoundingClientRect();
      const stickyHead = drawer.querySelector<HTMLElement>(".selected-job-drawer-head");
      const top = drawer.scrollTop + targetRect.top - drawerRect.top - stickyHeaderClearance(drawer, stickyHead, 12);
      drawer.scrollTo({
        top: Math.max(0, top),
        left: 0,
        behavior: androidScrollFix ? "auto" : "smooth",
      });
      return;
    }

    drawer.scrollTo({
      top: 0,
      left: 0,
      behavior: androidScrollFix ? "auto" : "smooth",
    });
    return;
  }

  selectedCardRef.current?.scrollIntoView({ behavior: "smooth", block: "nearest" });
}

function handleJobDrawerScroll(event: any) {
  const drawer = event.currentTarget as HTMLElement;
  if (!selectedOnly || !selected) {
    setJobCardHeaderFolded(false);
    return;
  }

  const shouldFold = drawer.scrollTop > 116;
  setJobCardHeaderFolded((current) => (current === shouldFold ? current : shouldFold));
}

function mapOverlayTouchTarget(target: EventTarget | null) {
  if (!(target instanceof Element)) return false;

  return Boolean(
    target.closest(
      ".job-drawer, .map-top, .map-menu-fab, .map-menu-scrim, .zoom-panel, .location-status-pill, button, a, input, select, textarea, summary, details"
    )
  );
}

function handleMapTouchStart(event: any) {
  if (mapOverlayTouchTarget(event.target)) {
    mapSwipeStartXRef.current = null;
    mapSwipeStartYRef.current = null;
    return;
  }

  const touch = event.touches?.[0];
  if (!touch) return;

  mapSwipeStartXRef.current = touch.clientX;
  mapSwipeStartYRef.current = touch.clientY;
}

function handleMapTouchEnd(event: any) {
  if (mapOverlayTouchTarget(event.target)) {
    mapSwipeStartXRef.current = null;
    mapSwipeStartYRef.current = null;
    return;
  }

  const startX = mapSwipeStartXRef.current;
  const startY = mapSwipeStartYRef.current;
  const touch = event.changedTouches?.[0];

  mapSwipeStartXRef.current = null;
  mapSwipeStartYRef.current = null;

  if (startX === null || startY === null || !touch) return;

  const dx = touch.clientX - startX;
  const dy = touch.clientY - startY;

  if (Math.abs(dy) > 80 || Math.abs(dx) < 70) return;
  if (!mapMenuOpen && startX <= 32 && dx > 0) openMapMenu();
  if (mapMenuOpen && dx < 0) closeMapMenu();
}


