                  !isRefused &&
                  !isWorkCompleted &&
                  !isPartialWork &&
                  counts.total === 0;
                const refusedChoices = refusedDescriptionChoices(selected);
                const refusedDescription = refusedDescriptionFromChoices(refusedChoices);
                const nextTitle = isRefused
