                const beforeUploadVideoStep = {
                  ...beforeVideoStep,
                  camera: false,
                  title: "Before Video Upload",
                  text: "Upload a before video. It will be labeled and saved with this job.",
                  label: beforeVideoStep.label.replace("Video", "Uploaded Video"),
                };
                const afterUploadPhotoStep = {
                  ...afterPhotoStep,
                  camera: false,
                  title: "After Image Upload",
                  text: "Upload an after image. It will be labeled and saved with this job.",
                  label: afterPhotoStep.label.replace("Photo", "Uploaded Image"),
                };
                const afterUploadVideoStep = {
                  ...afterVideoStep,
                  camera: false,
                  title: "After Video Upload",
                  text: "Upload an after video. It will be labeled and saved with this job.",
                  label: afterVideoStep.label.replace("Video", "Uploaded Video"),
                };
                const mediaStepCue = counts.before === 0
                  ? {
                      tone: "before",
                      eyebrow: "Step 1",
                      title: "Add Before Media",
                      detail: "Take or upload before image/video first.",
                    }
                  : counts.after === 0
                    ? {
                        tone: "after",
                        eyebrow: "Step 2",
                        title: "Add After Media",
                        detail: "Finish with after image/video when work is done.",
                      }
                    : {
                        tone: "review",
                        eyebrow: "Media Ready",
                        title: `${counts.total} file${counts.total === 1 ? "" : "s"} saved`,
                        detail: "Review media, then package.",
                      };
                const activeWorkChoice = fieldWorkChoice?.jobKey === jobKey(selected) ? fieldWorkChoice : null;
                const finishChoicePartial = Boolean(activeWorkChoice?.partial);
                const packageReadinessItems = [
                  {
                    key: "status",
                    label: "Status",
                    detail: currentStatusLabel,
                    done: Boolean(savedStatusIso && currentStatusLabel !== "Pending"),
                  },
                  {
                    key: "date",
                    label: "Date",
                    detail: savedStatusIso ? savedStatusDateLabel : "Not saved",
                    done: Boolean(savedStatusIso),
                  },
                  {
                    key: "media",
                    label: "Media",
                    detail: counts.total ? `${counts.total} file(s)` : canGenerateWithoutMedia || hasOptionalNoWorkEvidence ? "Optional" : "None",
                    done: Boolean(counts.total || canGenerateWithoutMedia || hasOptionalNoWorkEvidence),
                  },
                  {
                    key: "pdf",
                    label: "Affidavit",
                    detail: invoicePacket || packageReady ? "PDF ready" : finalOutcome ? "Ready to generate" : "Waiting",
                    done: Boolean(invoicePacket || packageReady),
                  },
                  {
                    key: "zip",
                    label: "ZIP",
                    detail: packageReady ? missionPackageLabel : "Not generated",
                    done: packageReady,
                  },
                  {
                    key: "review",
                    label: "Review",
                    detail: packageReviewApproved ? "Approved" : packageReady ? "Needs approval" : "Pending",
                    done: packageReviewApproved,
                  },
                ];
                const packageReadinessDoneCount = packageReadinessItems.filter((item) => item.done).length;
                const packageReadinessScore = Math.round((packageReadinessDoneCount / packageReadinessItems.length) * 100);
                const packageReadinessTone = packageReviewApproved
                  ? "approved"
                  : packageReady
                    ? "ready"
                    : packageReadinessScore >= 67
                      ? "almost"
                      : packageReadinessScore >= 34
                        ? "working"
                        : "start";
                const packageReadinessTitle = packageReviewApproved
